using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using Object=UnityEngine.Object;
public static class RebirthTurretMeshBudget {
 public static void Run(){var items=AssetBundle.LoadFromFile("C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/Data/Addressables/Standalone/automatic_assets_other/items.bundle");var bundle=AssetBundle.LoadFromFile(RebirthNativeTurretSurvey.Bundle);var rows=new List<string>();foreach(var kind in new[]{"SMG","Shotgun","M60"}){var path=bundle.GetAllAssetNames().Single(n=>n.ToLowerInvariant().EndsWith("autoturret"+kind.ToLowerInvariant()+"prefab.prefab"));var root=Object.Instantiate(bundle.LoadAsset<GameObject>(path));for(int lod=0;lod<3;lod++){int tris=0,verts=0;foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.EndsWith("LOD"+lod))){var mesh=mf.sharedMesh;if(!mesh)continue;int count=0;for(int s=0;s<mesh.subMeshCount;s++)count+=(int)mesh.GetIndexCount(s)/3;tris+=count;verts+=mesh.vertexCount;rows.Add(kind+" LOD"+lod+" part="+mf.name+" triangles="+count+" vertices="+mesh.vertexCount);}foreach(var sk in root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(f=>f.name.EndsWith("LOD"+lod))){var mesh=sk.sharedMesh;if(!mesh)continue;int count=0;for(int s=0;s<mesh.subMeshCount;s++)count+=(int)mesh.GetIndexCount(s)/3;tris+=count;verts+=mesh.vertexCount;rows.Add(kind+" LOD"+lod+" skinned="+sk.name+" triangles="+count+" vertices="+mesh.vertexCount);}rows.Add("TOTAL "+kind+" LOD"+lod+" triangles="+tris+" vertices="+verts);}Object.DestroyImmediate(root);}File.WriteAllLines("E:/_Haven/shared/REBIRTHStaged/VehicleStudio/TripoTurret_20261018/native-triangle-budget.txt",rows);}
}
